const input = typeof query === 'string' ? query : JSON.stringify(query);

function getValue(label) {
  const pattern = new RegExp(
    label + '\\s*[:=]\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)',
    'i'
  );
  const match = input.match(pattern);

  if (!match) {
    throw new Error('Missing input: ' + label);
  }

  const value = Number(match[1].replace(/,/g, ''));

  if (!Number.isFinite(value) || value < 0) {
    throw new Error('Invalid value: ' + label);
  }

  return value;
}

const actualRevenue = getValue('Actual Revenue');
const actualExpenses = getValue('Actual Operating Expenses');
const budgetRevenue = getValue('Budget Revenue');
const budgetExpenses = getValue('Budget Operating Expenses');

const actualProfit = actualRevenue - actualExpenses;
const budgetProfit = budgetRevenue - budgetExpenses;

function percent(value, base) {
  return base === 0 ? null : Number((value / base * 100).toFixed(2));
}

const result = {
  actualOperatingProfit: actualProfit,
  budgetOperatingProfit: budgetProfit,
  actualProfitMargin: percent(actualProfit, actualRevenue),
  budgetProfitMargin: percent(budgetProfit, budgetRevenue),
  revenueVariance: actualRevenue - budgetRevenue,
  revenueVariancePercent: percent(actualRevenue - budgetRevenue, budgetRevenue),
  expenseVariance: actualExpenses - budgetExpenses,
  expenseVariancePercent: percent(actualExpenses - budgetExpenses, budgetExpenses),
  operatingProfitVariance: actualProfit - budgetProfit,
  operatingProfitVariancePercent: percent(actualProfit - budgetProfit, Math.abs(budgetProfit))
};

return JSON.stringify(result);

const input = typeof query === 'string' ? query : JSON.stringify(query);

function getValue(label) {
  const pattern = new RegExp(
    label + '\\s*[:=]\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)',
    'i'
  );
  const match = input.match(pattern);

  if (!match) throw new Error('Missing input: ' + label);

  const value = Number(match[1].replace(/,/g, ''));
  if (!Number.isFinite(value) || value < 0) {
    throw new Error('Invalid value: ' + label);
  }
  return value;
}

const openingCash = getValue('Opening Cash');
const inflows = getValue('Total Cash Inflows');
const outflows = getValue('Total Cash Outflows');
const minimumCash = getValue('Minimum Required Cash');

const netCashFlow = inflows - outflows;
const closingCash = openingCash + netCashFlow;
const surplus = closingCash - minimumCash;

const result = {
  openingCash,
  totalCashInflows: inflows,
  totalCashOutflows: outflows,
  netCashFlow,
  closingCash,
  minimumRequiredCash: minimumCash,
  liquiditySurplusOrShortfall: surplus,
  liquidityStatus: surplus >= 0 ? 'Sufficient' : 'Shortfall',
  risk: closingCash < minimumCash ? 'High' : 'Within minimum threshold'
};

return JSON.stringify(result);
